  1984  int SuggestMgr::ngram(int n,
  1985                        const std::string& s1,
  1986                        const std::string& s2,
  1987                        int opt) {
  1988    int nscore = 0;
  1989    int ns;
  1990    int l1;
  1991    int l2;
  1992    int test = 0;
  1993
  1994    l2 = s2.size();
  1995    if (l2 == 0)
  1996      return 0;
  1997    l1 = s1.size();
  1998    for (int j = 1; j <= n; j++) {
  1999      ns = 0;
  2000      for (int i = 0; i <= (l1 - j); i++) {
  2001        //s2 is haystack, s1[i..i+j) is needle
  2002        if (s2.find(s1.c_str()+i, 0, j) != std::string::npos) {
  2003          ns++;
  2004        } else if (opt & NGRAM_WEIGHTED) {
  2005          ns--;
  2006          test++;
  2007          if (i == 0 || i == l1 - j)
  2008            ns--;  // side weight
  2009        }
  2010      }
  2011      nscore = nscore + ns;
  2012      if (ns < 2 && !(opt & NGRAM_WEIGHTED))
  2013        break;
  2014    }
  2015
  2016    ns = 0;
  2017    if (opt & NGRAM_LONGER_WORSE)
  2018      ns = (l2 - l1) - 2;
  2019    if (opt & NGRAM_ANY_MISMATCH)
